let CONV_PREFIX_KOTLIN = "KOTLIN-"
let CONV_PREFIX_SWIFT = "SWIFT-"
let CONV_PROMPT_PREFIX = """
You are a transpiler that converts Swift source code into idiomatic Kotlin source code.

Rules you must always follow:
- Output ONLY the transpiled Kotlin code as numbered KOTLIN-n blocks matching the format of the example below. Never repeat, quote, or echo the input Swift code.
- Never add leading titles, bullet points, explanations, or prose before the KOTLIN-0 block. Never add trailing notes, greetings, or text after the last KOTLIN-n block.
- Never wrap the output in markdown code fences or backticks.
- Never add blank lines anywhere: neither between blocks nor inside a block.
- Preserve the exact shape of every fragment. A block with N lines in the input MUST have exactly N lines in the output, in the same order: never merge two lines into one, never split one line into two
- Preserve indentation for each source code line
- Emit only the fragment itself with the token conversions below applied. Never add an enclosing statement, braces, or any surrounding syntax that was not in the input.
- Convert Swift 'x.isEmpty' (Bool property, no parentheses) into the Kotlin function call 'x.isEmpty()'. The Swift '!c.countText.isEmpty' MUST become '!c.countText.isEmpty()' with parentheses, because Kotlin requires the call.
- Convert Swift string interpolation '\\(expr)' to Kotlin '${expr}'.
- Convert a Swift force unwrap 'x!' to the Kotlin non-null assertion 'x!!'. For example 'c.singleton!.countText' must become 'c.singleton!!.countText' — add the second '!'.
- Convert a Swift force cast 'x as! T' to Kotlin 'x as T'. For example 'RootVM.shared as! RootVM' must become 'RootVM.shared as RootVM' — remove the '!'.
- Convert Swift array literals '[a, b]' to Kotlin 'listOf(a, b)'.
- Convert Swift trailing closures '{ x in ... }' to Kotlin lambdas '{ x -> ... }'.
- Convert a Swift ternary 'a ? b : c' to Kotlin 'if (a) b else c'.
- Convert a Swift force cast 'x as! T' to Kotlin 'x as T'.

Study this example of a correct Swift-to-Kotlin transpilation and match its format exactly:

SWIFT INPUT
===
\(CONV_EXAMPLE_SWIFT_SRC)
KOTLIN OUTPUT
===
\(CONV_EXAMPLE_KOTLIN_DST)
Transpile the following Swift input:
"""
let CONV_PROMPT_SUFFIX = """

Kotlin output:
"""

func convQueuePrompt(
    _ queue: [String],
    _ id: Int
) -> String {
    let src = CONV_PREFIX_SWIFT + String(id) + "\n" + queue[id]
    return CONV_PROMPT_PREFIX + src + CONV_PROMPT_SUFFIX
}

// Build a flat queue of oneliner reactions to transpile
func convSrcQueueOneliners(
    _ entityOneliners: [Int: [Oneliner]]
) -> [String] {
    var items = [String]()
    for entityId in entityOneliners.keys.sorted() {
        let oneliners = entityOneliners[entityId] ?? []
        for oneliner in oneliners {
            items.append(oneliner.reaction)
        }
    }

    return items
}

// Build a flat queue of shoulds to transpile
func convSrcQueueShoulds(
    _ entityShouldBranches: [Int: [Int: [ShouldBranch]]]
) -> [String] {
    var items = [String]()
    for entityId in entityShouldBranches.keys.sorted() {
        let shoulds = entityShouldBranches[entityId] ?? [:]
        for shouldId in shoulds.keys.sorted() {
            let branches = shoulds[shouldId] ?? []
            for branch in branches {
                items.append(branch.condition.joined(separator: "\n"))
                items.append(branch.reaction.joined(separator: "\n"))
            }
        }
    }

    return items
}

// Construct single transpiled oneliner
func convTranspiledOneliner(
    _ orig: Oneliner,
    _ reac: String
) -> Oneliner {
    var o = orig

    var linesReaction = reac.split(separator: "\n")
    if
        let first = linesReaction.first,
        first.hasPrefix(CONV_PREFIX_KOTLIN)
    {
        linesReaction = Array(linesReaction.dropFirst())
        o.reaction = linesReaction.joined(separator: "\n")
    }

    return o
}

// Construct several transpiled oneliners
func convTranspiledOneliners(
    _ entityOneliners: [Int: [Oneliner]],
    _ dstQueue: [String]
) -> [Int: [Oneliner]] {
    var items = [Int: [Oneliner]]()
    var id = 0
    for entityId in entityOneliners.keys.sorted() {
        let oneliners = entityOneliners[entityId] ?? []
        for oneliner in oneliners {
            // Get transpiled snippet
            let reaction = dstQueue[id]
            id += 1
            // Format the snippet
            let item = convTranspiledOneliner(oneliner, reaction)
            items[entityId, default: []].append(item)
        }
    }

    return items
}

// Construct single transpiled branch
func convTranspiledShouldBranch(
    _ orig: ShouldBranch,
    _ cond: String,
    _ reac: String
) -> ShouldBranch {
    var b = orig

    var linesCondition = cond.split(separator: "\n")
    if
        let first = linesCondition.first,
        first.hasPrefix(CONV_PREFIX_KOTLIN)
    {
        linesCondition = Array(linesCondition.dropFirst())
        b.condition = linesCondition.map(String.init)
    }

    var linesReaction = reac.split(separator: "\n")
    if
        let first = linesReaction.first,
        first.hasPrefix(CONV_PREFIX_KOTLIN)
    {
        linesReaction = Array(linesReaction.dropFirst())
        b.reaction = linesReaction.map(String.init)
    }

    return b
}

// Construct serveral transpiled branches
func convTranspiledShouldBranches(
    _ entityShouldBranches: [Int: [Int: [ShouldBranch]]],
    _ dstQueue: [String]
) -> [Int: [Int: [ShouldBranch]]] {
    var items = [Int: [Int: [ShouldBranch]]]()
    var id = 0
    for entityId in entityShouldBranches.keys.sorted() {
        let shoulds = entityShouldBranches[entityId] ?? [:]
        for shouldId in shoulds.keys.sorted() {
            let branches = shoulds[shouldId] ?? []
            for branch in branches {
                // Get transpiled snippets
                let condition = dstQueue[id]
                id += 1
                let reaction = dstQueue[id]
                id += 1
                // Format the snippets
                let item = convTranspiledShouldBranch(branch, condition, reaction)
                items[entityId, default: [:]][shouldId, default: []].append(item)
            }
        }
    }

    return items
}

