import Foundation

func llmBody(_ prompt: String) -> String {
    let payload: [String: Any] = [
        "model": LLM_DEFAULT_MODEL,
        "options": [
            "seed": LLM_SEED,
            "temperature": LLM_TEMPERATURE,
            "top_k": LLM_TOP_K
        ],
        "prompt": prompt,
        "stream": false
    ]

    guard
        let data = try? JSONSerialization.data(withJSONObject: payload)
    else {
        return ""
    }

    return String(data: data, encoding: .utf8) ?? ""
}

// Extract "reponse" out of JSON
func llmExtractReply(_ json: String) -> String {
    let lines = json.components(separatedBy: LLM_LINE_DELIMITER)

    for ln in lines {
        if ln.hasPrefix(LLM_REPLY_PREFIX) {
            return llmUnescape(String(ln.dropFirst(LLM_REPLY_PREFIX.count)))
        }
    }

    return "ERROR Could not parse response"
}

func llmReqPrompt(
    _ host: String,
    _ port: Int,
    _ prompt: String
) -> NetRequest {
    var req = NetRequest()
    req.headers = [NET_CONTENT_TYPE: NET_APP_JSON]
    req.method = NET_POST
    req.url = LLM_URL_GENERATE_T
        .replacingOccurrences(of: "%HOST%", with: host)
        .replacingOccurrences(of: "%PORT%", with: "\(port)")
    req.body = llmBody(prompt)

    return req
}

func llmUnescape(_ str: String) -> String {
    var out = String()
    var idx = str.startIndex

    while idx < str.endIndex {
        let ch = str[idx]
        let nextIdx = str.index(after: idx)

        guard ch == "\\", nextIdx < str.endIndex else {
            out.append(ch)
            idx = nextIdx
            continue
        }

        let esc = str[nextIdx]
        let afterEsc = str.index(after: nextIdx)

        switch esc {
        case "\"":
            out.append("\"")
        case "\\":
            out.append("\\")
        case "/":
            out.append("/")
        case "b":
            out.append("\u{08}")
        case "f":
            out.append("\u{0C}")
        case "n":
            out.append("\n")
        case "r":
            out.append("\r")
        case "t":
            out.append("\t")
        case "u":
            guard str.distance(from: afterEsc, to: str.endIndex) >= 4 else {
                out.append(ch)
                out.append(esc)
                idx = afterEsc
                continue
            }
            let hexEnd = str.index(afterEsc, offsetBy: 4)
            let hex = String(str[afterEsc ..< hexEnd])
            guard var code = UInt32(hex, radix: 16) else {
                out.append(ch)
                out.append(esc)
                idx = afterEsc
                continue
            }
            idx = hexEnd
            if (0xD800 ... 0xDFFF).contains(code),
                str.distance(from: idx, to: str.endIndex) >= 6,
                str[idx] == "\\", str[str.index(after: idx)] == "u"
            {
                let lowStart = str.index(idx, offsetBy: 2)
                let lowEnd = str.index(lowStart, offsetBy: 4)
                if let low = UInt32(String(str[lowStart ..< lowEnd]), radix: 16),
                    (0xDC00 ... 0xDFFF).contains(low)
                {
                    code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                    idx = lowEnd
                }
            }
            if let scalar = Unicode.Scalar(code) {
                out.append(Character(scalar))
            } else {
                out.append(contentsOf: "\\u" + hex)
            }
            continue
        default:
            out.append(ch)
            out.append(esc)
            idx = afterEsc
            continue
        }

        idx = afterEsc
    }

    return out
}

import Foundation

func netLoad(
    _ req: NetRequest,
    _ reportSuccess: @escaping (NetResponse) -> Void,
    _ reportError: @escaping (NetResponse) -> Void
) {
    var res = NetResponse()
    res.req = req

    guard
        let url = URL(string: req.url)
    else {
        res.contents = NET_INVALID_URL
        reportError(res)
        return
    }

    var r = URLRequest(url: url)
    r.httpMethod = req.method
    r.httpBody = req.body.isEmpty ? nil : req.body.data(using: .utf8)
    for (key, value) in req.headers {
        r.setValue(value, forHTTPHeaderField: key)
    }

    let session = URLSession(configuration: .ephemeral)
    session.dataTask(with: r) { data, response, error in
        if let error = error {
            res.contents = "\(error)"
            reportError(res)
        } else if let http = response as? HTTPURLResponse,
            !(200 ..< 300).contains(http.statusCode) {
            let body = data.flatMap { String(data: $0, encoding: .utf8) } ?? ""
            res.contents = "\(http.statusCode) \(body)"
            reportError(res)
        } else if let data = data {
            res.contents = String(data: data, encoding: .utf8) ?? ""
            reportSuccess(res)
        }
    }.resume()
}

let NET_APP_JSON = "application/json"
let NET_CONTENT_TYPE = "Content-Type"
let NET_INVALID_URL = "Invalid URL"
let NET_POST = "POST"

import Foundation

/// Decode a base64 string back into a regular string
func otherBase64ToString(_ encoded: String) -> String {
    guard
        let data = Data(base64Encoded: encoded),
        let str = String(data: data, encoding: .utf8)
    else {
        return ""
    }
    return str
}

/// Capitalize the first letter of a string
func otherCapitalize(_ s: String) -> String {
    guard let first = s.first else {
        return s
    }
    return String(first).uppercased() + String(s.dropFirst())
}

/// Launch to wait for asynchrnous actions
func otherLaunch() {
    RunLoop.current.run()
}

/// Count leading spaces in a line
func otherLineIndent(_ line: String) -> Int {
    var count = 0
    for ch in line {
        if ch == " " {
            count += 1
        } else {
            break
        }
    }
    return count
}

/// Print to stderr
func otherPrintStderr(_ txt: String) {
    if let dat = "\(txt)\n".data(using: .utf8) {
        FileHandle.standardError.write(dat)
    }
}

/// Print each key/value processed by a controller into stderr
func otherSetupConsoleLogging(
    _ ctrl: DialectController,
    _ prefix: String
) {
    ctrl.registerCallback { c -> Void in
        let value = c.fieldAny(c.recentField)
        let line = "ИГР \(prefix) k/v: '\(c.recentField)'/'\(value)'"
        otherPrintStderr(line)
    }
}

/// Write output text to a file
func otherWriteFile(
    _ path: String,
    _ content: String
) {
    try? content.write(toFile: path, atomically: true, encoding: .utf8)
}

/// Terminate the main RunLoop
func otherShutdown() {
    exit(0)
}

