"""
let SWIFT_REGISTER_EFFECTS_SUFFIX = "RegisterEffects"
let SWIFT_REGISTER_EFFECTS_T = """

func %FUNC%(_ ctrl: DialectController) {
    let _: %CONTEXT%? = registerOneliners(ctrl, [
