}

"""
let SWIFT_REGISTER_EFFECT_ITEM_T = """
        F.%FIELD%, { (c: %CONTEXT%) in %REACTION% },

"""
let SWIFT_REGISTER_SHOULDS_SUFFIX = "RegisterShoulds"
let SWIFT_REGISTER_SHOULDS_T = """

func %FUNC%(_ ctrl: DialectController) {
    [
%ITEMS%
    ].forEach { f in
        ctrl.registerFunction { c in f(c as! %CONTEXT%) }
    }
}

"""
let SWIFT_SET_SUFFIX = "Set"
let SWIFT_SET_T = """

func %FUNC%(
    _ key: String,
    _ value: Any
) {
    %COMPONENT%.singleton!.ctrl.set(key, value)
}

"""
let SWIFT_STRUCT_FIELD_T = "    var %NAME% = %DEFAULT%\n"
let SWIFT_STRUCT_T = """

struct %NAME% {
%FIELDS%
}


"""
let SWIFT_SHOULD_BRANCH_T = """
    /* %ABOUT% */
    if
%CONDITION%
    {
%REACTION%
        c.recentField = F.%FIELD%
        return c
    }


"""
let SWIFT_SHOULD_INDENTATION = "        "
let SWIFT_SHOULD_RESET = "ShouldReset"
let SWIFT_SHOULD_T = """

func %FUNC%(_ c: %CONTEXT%) -> %CONTEXT% {
    var c = c

%BRANCHES%
    c.recentField = DIALECT_CONTEXT_RECENT_FIELD_NONE
    return c
}

"""
let SWIFT_SUFFIX_COMPONENT = "Component"
let SWIFT_SUFFIX_CONTEXT = "Context"
let SWIFT_TYPE = "swift"
let SWIFT_TYPE_COMPONENT = "component"
let SWIFT_TYPE_CONTEXT = "context"
let SWIFT_TYPE_STRUCT = "struct"

let SWIFT_EMB64_CORE=""

import Foundation

/// Generate single `context` entity
func swiftContext(
    _ name: String,
    _ fields: [String],
    _ fieldTypes: [Int: String]
) -> String {
    var outFields = ""
    var outGetters = ""
    var outSetters = ""
    var fieldId = 0
    for field in fields {
        let els = (fieldId == 0) ? "" : "else "
        let type = fieldTypes[fieldId]!
        let defaultValue = swiftTypeDefaultValue(type)
        outFields +=
            SWIFT_CONTEXT_FIELD_T
                .replacingOccurrences(of: "%DEFAULT%", with: defaultValue)
                .replacingOccurrences(of: "%NAME%", with: field)
        outGetters +=
            SWIFT_CONTEXT_GETTER_T
                .replacingOccurrences(of: "%ELSE%", with: els)
                .replacingOccurrences(of: "%NAME%", with: field)
        outSetters +=
            SWIFT_CONTEXT_SETTER_T
                .replacingOccurrences(of: "%ELSE%", with: els)
                .replacingOccurrences(of: "%NAME%", with: field)
                .replacingOccurrences(of: "%TYPE%", with: type)
        fieldId += 1
    }

    return
        SWIFT_CONTEXT_T
            .replacingOccurrences(of: "%NAME%", with: name)
            .replacingOccurrences(of: "%FIELDS%", with: outFields)
            .replacingOccurrences(of: "%GETTERS%", with: outGetters)
            .replacingOccurrences(of: "%SETTERS%", with: outSetters)
}

/// Generate the context name for a component
func swiftContextName(_ entity: String) -> String {
    return entity.replacingOccurrences(of: SWIFT_SUFFIX_COMPONENT, with: SWIFT_SUFFIX_CONTEXT)
}

/// Generate entities of `context` type
func swiftContexts(
    _ entities: [String],
    _ entityTypes: [Int: String],
    _ entityFields: [Int: [String]],
    _ entityFieldTypes: [Int: [Int: String]]
) -> String {
    var out = ""

    // Locate contexts
    var entityId = 0
    var contextIds = [Int]()
    for _ in entities {
        let type = entityTypes[entityId]
        if type == SWIFT_TYPE_CONTEXT {
            contextIds.append(entityId)
        }
        entityId += 1
    }

    // Generate each context
    for id in contextIds {
        out +=
            swiftContext(
                entities[id],
                entityFields[id]!,
                entityFieldTypes[id]!
            )
    }

    return out
}

/// Generate `struct F` holding one string constant per field name
func swiftFields(_ entityFields: [Int: [String]]) -> String {
    var names = Set<String>()

    // Collect field names
    for fields in entityFields.values {
        for field in fields {
            names.insert(field)
        }
    }

    // Construct the body of the struct
    var sitems = ""
    for name in names.sorted() {
        sitems += SWIFT_FIELD_T.replacingOccurrences(of: "%NAME%", with: name)
    }

    // Construct the whole struct
    return SWIFT_FIELDS_T.replacingOccurrences(of: "%ITEMS%", with: sitems)
}

/// Join branch lines, indenting each by 8 spaces while keeping relative indent
func swiftFormatShould(_ lines: [String]) -> String {
    return lines.map { SWIFT_SHOULD_INDENTATION + $0 }.joined(separator: "\n")
}

/// Generate single component `RegisterEffects` function
func swiftRegisterEffect(
    _ contextName: String,
    _ oneliners: [Oneliner]
) -> String {
    let prefix = String(contextName.dropLast(SWIFT_SUFFIX_CONTEXT.count)).lowercased()
    let funcName = prefix + SWIFT_REGISTER_EFFECTS_SUFFIX

    var outItems = ""
    for oneliner in oneliners {
        let field = oneliner.field
        let reaction = oneliner.reaction
        outItems +=
            SWIFT_REGISTER_EFFECT_ITEM_T
                .replacingOccurrences(of: "%CONTEXT%", with: contextName)
                .replacingOccurrences(of: "%FIELD%", with: field)
                .replacingOccurrences(of: "%REACTION%", with: reaction)
    }

    return
        SWIFT_REGISTER_EFFECTS_T
            .replacingOccurrences(of: "%FUNC%", with: funcName)
            .replacingOccurrences(of: "%CONTEXT%", with: contextName)
            .replacingOccurrences(of: "%ITEMS%", with: outItems)
}

/// Generate `RegisterEffects` functions for all components
func swiftRegisterEffects(
    _ entities: [String],
    _ entityOneliners: [Int: [Oneliner]]
) -> String {
    var out = ""

    // Collect entity ids with oneliners
    var entityIds = [Int]()
    for entityId in entityOneliners.keys.sorted() {
        let oneliners = entityOneliners[entityId]!
        if !oneliners.isEmpty {
            entityIds.append(entityId)
        }
    }

    // Generate register-effects function for each component
    for entityId in entityIds {
        let contextName = swiftContextName(entities[entityId])

        let oneliners = entityOneliners[entityId] ?? []
        if !oneliners.isEmpty {
            out += swiftRegisterEffect(contextName, oneliners)
        }
    }

    return out
}

/// Generate single component `RegisterShoulds` function
func swiftRegisterShould(
    _ contextName: String,
    _ shoulds: [String]
) -> String {
    let prefix = String(contextName.dropLast(SWIFT_SUFFIX_CONTEXT.count)).lowercased()
    let funcName = prefix + SWIFT_REGISTER_SHOULDS_SUFFIX

    var outItems = ""
    for should in shoulds {
        let shouldFuncName = prefix + SWIFT_SHOULD_RESET + otherCapitalize(should)
        outItems += SWIFT_SHOULD_INDENTATION + shouldFuncName + ",\n"
    }

    return
        SWIFT_REGISTER_SHOULDS_T
            .replacingOccurrences(of: "%FUNC%", with: funcName)
            .replacingOccurrences(of: "%CONTEXT%", with: contextName)
            .replacingOccurrences(of: "%ITEMS%", with: outItems)
}

/// Generate `RegisterShoulds` functions for all components
func swiftRegisterShoulds(
    _ entities: [String],
    _ entityShoulds: [Int: [String]]
) -> String {
    var out = ""

    // Collect entity ids with shoulds
    var entityIds = [Int]()
    for entityId in entityShoulds.keys.sorted() {
        let shoulds = entityShoulds[entityId]!
        if !shoulds.isEmpty {
            entityIds.append(entityId)
        }
    }

    // Generate register-shoulds function for each component
    for entityId in entityIds {
        let contextName = swiftContextName(entities[entityId])

        let shoulds = entityShoulds[entityId] ?? []
        if !shoulds.isEmpty {
            out += swiftRegisterShould(contextName, shoulds)
        }
    }

    return out
}

/// Generate single component `Set` function
func swiftSet(_ entity: String) -> String {
    let contextName = swiftContextName(entity)
    let prefix = String(contextName.dropLast(SWIFT_SUFFIX_CONTEXT.count)).lowercased()
    let funcName = prefix + SWIFT_SET_SUFFIX

    return
        SWIFT_SET_T
            .replacingOccurrences(of: "%FUNC%", with: funcName)
            .replacingOccurrences(of: "%COMPONENT%", with: entity)
}

/// Generate `Set` functions for all components
func swiftSets(_ entities: [String]) -> String {
    var out = ""

    // Generate each component's `Set` function
    for entity in entities {
        if entity.hasSuffix(SWIFT_SUFFIX_COMPONENT) {
            out += swiftSet(entity)
        }
    }

    return out
}

/// Generate single should function
func swiftShould(
    _ name: String,
    _ contextName: String,
    _ branches: [ShouldBranch]
) -> String {
    var outBranches = ""
    for branch in branches {
        outBranches +=
            SWIFT_SHOULD_BRANCH_T
                .replacingOccurrences(of: "%ABOUT%", with: branch.about)
                .replacingOccurrences(of: "%FIELD%", with: name)
                .replacingOccurrences(of: "%CONDITION%", with: swiftFormatShould(branch.condition))
                .replacingOccurrences(of: "%REACTION%", with: swiftFormatShould(branch.reaction))
    }

    let prefix = String(contextName.dropLast(SWIFT_SUFFIX_CONTEXT.count)).lowercased()
    let funcName = prefix + SWIFT_SHOULD_RESET + otherCapitalize(name)

    return
        SWIFT_SHOULD_T
            .replacingOccurrences(of: "%FUNC%", with: funcName)
            .replacingOccurrences(of: "%CONTEXT%", with: contextName)
            .replacingOccurrences(of: "%BRANCHES%", with: outBranches)
}

/// Generate should-functions for all components
func swiftShoulds(
    _ entities: [String],
    _ entityShoulds: [Int: [String]],
    _ entityShouldBranches: [Int: [Int: [ShouldBranch]]]
) -> String {
    var out = ""

    // Collect entity ids with shoulds
    var entityIds = [Int]()
    for entityId in entityShoulds.keys.sorted() {
        let shoulds = entityShoulds[entityId]!
        if !shoulds.isEmpty {
            entityIds.append(entityId)
        }
    }

    // Generate should-functions for each component
    for entityId in entityIds {
        let contextName = swiftContextName(entities[entityId])

        let shoulds = entityShoulds[entityId] ?? []
        var shouldId = 0
        for should in shoulds {
            let branches = entityShouldBranches[entityId]?[shouldId] ?? []
            if !branches.isEmpty {
                out += swiftShould(should, contextName, branches)
            }
            shouldId += 1
        }
    }

    return out
}

/// Generate single `struct` entity
func swiftStruct(
    _ name: String,
    _ fields: [String],
    _ fieldTypes: [Int: String]
) -> String {
    var outFields = ""
    var fieldId = 0
    for field in fields {
        let type = fieldTypes[fieldId]!
        let defaultValue = swiftTypeDefaultValue(type)
        outFields +=
            SWIFT_STRUCT_FIELD_T
                .replacingOccurrences(of: "%NAME%", with: field)
                .replacingOccurrences(of: "%DEFAULT%", with: defaultValue)
        fieldId += 1
    }
    return
        SWIFT_STRUCT_T
            .replacingOccurrences(of: "%NAME%", with: name)
            .replacingOccurrences(of: "%FIELDS%", with: outFields)
}

/// Generate entities of `struct` type
func swiftStructs(
    _ entities: [String],
    _ entityTypes: [Int: String],
    _ entityFields: [Int: [String]],
    _ entityFieldTypes: [Int: [Int: String]]
) -> String {
    var out = ""

    // Locate structs
    var entityId = 0
    var structIds = [Int]()
    for _ in entities {
        let type = entityTypes[entityId]
        if type == SWIFT_TYPE_STRUCT {
            structIds.append(entityId)
        }
        entityId += 1
    }

    // Generate each struct
    for id in structIds {
        out +=
            swiftStruct(
                entities[id],
                entityFields[id]!,
                entityFieldTypes[id]!
            )
    }

    return out
}

/// Generate default value for a type
func swiftTypeDefaultValue(_ type: String) -> String {
    return "\(type)()"
}

class YMLComponent {
    let ctrl = DialectController(YMLContext())
    static private(set) weak var singleton: YMLComponent?

    init() {
        Self.singleton = self
        ymlRegisterEffects(ctrl)
        ymlRegisterShoulds(ctrl)
    }

    func setup() {
        ymlSet(F.didSetup, true)
    }
}




let YML_FIELD_DELIMITER = ": "
let YML_INDENT_SHOULD = 8
let YML_INDENT_SHOULD_BRANCH_DESC = 12
let YML_INDENT_SHOULD_BRANCH_IF = 20
let YML_INDENT_SHOULD_BRANCH_THEN = 20
let YML_PREFIX_FIELD = "        "
let YML_PREFIX_FIELDS = "    fields:"
let YML_PREFIX_ONELINER = "        - "
let YML_PREFIX_ONELINERS = "    oneliners:"
let YML_PREFIX_OUTPUT = "output:"
let YML_PREFIX_OUTPUT_PATH = "    "
let YML_PREFIX_OUTPUT_TYPE = "        type: "
let YML_PREFIX_SHOULD_BRANCH_IF = "                if:"
let YML_PREFIX_SHOULD_BRANCH_THEN = "                then:"
let YML_PREFIX_SHOULDS = "    shoulds:"
let YML_PREFIX_TYPE = "    type: "
let YML_PREFIX_VERSION = "version: "

func ymlReadLines(_ input: String) {
    let lines = input.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
    ymlSet(F.inputLines, lines)
}

func ymlIsLineChunkEnd(_ ln: String) -> Bool {
    return ln.isEmpty
}

func ymlIsLineChunkStart(_ ln: String) -> Bool {
    // A line is the start of a chunk if:
    // 1. it has no indentation
    // 2. it is not empty
    return !ln.hasPrefix(" ") && !ln.isEmpty
}

func ymlParseChunks(_ lines: [String]) -> [String: [String]] {
    var chunks = [String: [String]]()
    var currentChunkLines = [String]()
    var isChunk = false

    for ln in lines {
        // Detect chunk start/end
        if ymlIsLineChunkEnd(ln) {
            isChunk = false
        }
        if ymlIsLineChunkStart(ln) {
            isChunk = true
        }

        // Collect chunk lines
        if isChunk {
            currentChunkLines.append(ln)
        }

        // Create chunk while parsing
        if
            !isChunk,
            let firstLine = currentChunkLines.first
        {
            chunks[firstLine] = currentChunkLines
        }

        // Flush collected chunk lines for the next chunk
        if !isChunk {
            currentChunkLines = []
        }
    }

    // Create chunk for the ending chunk
    if let firstLine = currentChunkLines.first {
        chunks[firstLine] = currentChunkLines
    }

    return chunks
}

func ymlParseEntities(_ chunks: [String: [String]]) -> [String] {
    var entities = [String]()

    for key in chunks.keys {
        // Ignore known non-entity chunks.
        if key == YML_PREFIX_OUTPUT {
            continue
        }
        if key.hasSuffix(":") {
            entities.append(String(key.dropLast(1)))
        }
    }

    return entities.sorted()
}

func ymlParseEntityFieldTypes(
    _ chunks: [String: [String]],
    _ entities: [String],
    _ entityFields: [Int: [String]]
) -> [Int: [Int: String]] {
    var result = [Int: [Int: String]]()
    var entityId = 0

    for entity in entities {
        guard let lines = chunks["\(entity):"] else {
            entityId += 1
            continue
        }

        var types = [Int: String]()
        var fieldId = 0
        var inFields = false

        for ln in lines {
            if ln.hasPrefix(YML_PREFIX_FIELDS) {
                inFields = true
                continue
            }
            if inFields && !ln.hasPrefix(YML_PREFIX_FIELD) {
                break
            }
            if inFields {
                let nameAndType = String(ln.dropFirst(YML_PREFIX_FIELD.count))
                let parts = nameAndType.split(
                    separator: YML_FIELD_DELIMITER,
                    maxSplits: 1,
                    omittingEmptySubsequences: false
                )
                if parts.count == 2 {
                    types[fieldId] = String(parts[1])
                    fieldId += 1
                }
            }
        }

        result[entityId] = types
        entityId += 1
    }

    return result
}

func ymlParseEntityFields(
    _ chunks: [String: [String]],
    _ entities: [String]
) -> [Int: [String]] {
    var result = [Int: [String]]()
    var i = 0

    for entity in entities {
        var fields = [String]()

        guard let lines = chunks["\(entity):"] else {
            i += 1
            continue
        }

        var inFields = false

        for ln in lines {
            if ln.hasPrefix(YML_PREFIX_FIELDS) {
                inFields = true
                continue
            }
            if inFields && !ln.hasPrefix(YML_PREFIX_FIELD) {
                break
            }
            if inFields {
                let name = String(ln.dropFirst(YML_PREFIX_FIELD.count).split(separator: ":")[0])
                fields.append(name)
            }
        }

        result[i] = fields
        i += 1
    }

    return result
}

func ymlParseEntityOneliners(
    _ chunks: [String: [String]],
    _ entities: [String]
) -> [Int: [Oneliner]] {
    var result = [Int: [Oneliner]]()

    var entityId = 0
    for entity in entities {
        var isParsing = false
        var oneliners = [Oneliner]()

        guard let lines = chunks["\(entity):"] else {
            entityId += 1
            continue
        }

        for ln in lines {
            // Detect oneliners' section
            if ln.hasPrefix(YML_PREFIX_ONELINERS) {
                isParsing = true
                continue
            }
            if ln.hasPrefix(YML_PREFIX_SHOULDS) {
                isParsing = false
                continue
            }

            if 
                isParsing &&
                ln.hasPrefix(YML_PREFIX_ONELINER)
            {
                let kv = String(ln.dropFirst(YML_PREFIX_ONELINER.count))
                let parts = kv.split(
                    separator: YML_FIELD_DELIMITER,
                    maxSplits: 1,
                    omittingEmptySubsequences: false
                )
                if parts.count == 2 {
                    var item = Oneliner()
                    item.field = String(parts[0])
                    item.reaction = String(parts[1])
                    oneliners.append(item)
                }
            }
        }

        result[entityId] = oneliners
        entityId += 1
    }

    return result
}

func ymlParseEntityShouldBranches(
    _ chunks: [String: [String]],
    _ entities: [String],
    _ entityShoulds: [Int: [String]]
) -> [Int: [Int: [ShouldBranch]]] {
    var result = [Int: [Int: [ShouldBranch]]]()

    // Collect entity ids with shoulds
    var entityIds = [Int]()
    for id in entityShoulds.keys.sorted() {
        let shoulds = entityShoulds[id]!
        if !shoulds.isEmpty {
            entityIds.append(id)
        }
    }

    // Collect should branches
    for entityId in entityIds {
        let entity = entities[entityId]
        guard let lines = chunks["\(entity):"] else { continue }

        var isParsing = false
        var isParsingCondition = false
        var isParsingReaction = false
        var shouldId = -1
        var shouldSections = [Int: [ShouldBranch]]()

        for ln in lines {

            // Detect parsed region
            if ln.hasPrefix(YML_PREFIX_SHOULDS) {
                isParsing = true
                continue
            }
            if !isParsing {
                continue
            }

            // Detect parsing `condition`
            if ln.hasPrefix(YML_PREFIX_SHOULD_BRANCH_IF) {
                isParsingCondition = true
                continue
            }
            if ln.hasPrefix(YML_PREFIX_SHOULD_BRANCH_THEN) {
                isParsingCondition = false
            }

            // Detect parsing `reaction`
            if ln.hasPrefix(YML_PREFIX_SHOULD_BRANCH_THEN) {
                isParsingReaction = true
                continue
            }
            if otherLineIndent(ln) == YML_INDENT_SHOULD {
                isParsingReaction = false
            }

            // Detect should section
            if otherLineIndent(ln) == YML_INDENT_SHOULD {
                shouldId += 1
                shouldSections[shouldId] = []
                continue
            }

            // Parse branch description
            if otherLineIndent(ln) == YML_INDENT_SHOULD_BRANCH_DESC {
                isParsingCondition = false
                isParsingReaction = false
                shouldSections[shouldId]!.append(ShouldBranch())
                let lastId = shouldSections[shouldId]!.count - 1
                let about = String(ln.dropFirst(YML_INDENT_SHOULD_BRANCH_DESC).dropLast())
                shouldSections[shouldId]![lastId].about = about
            }

            // Parse branch condition
            if isParsingCondition {
                let lastId = shouldSections[shouldId]!.count - 1
                let condition = String(ln.dropFirst(YML_INDENT_SHOULD_BRANCH_IF))
                shouldSections[shouldId]![lastId].condition.append(condition)
            }

            // Parse branch reaction
            if isParsingReaction {
                let lastId = shouldSections[shouldId]!.count - 1
                let reaction = String(ln.dropFirst(YML_INDENT_SHOULD_BRANCH_THEN))
                shouldSections[shouldId]![lastId].reaction.append(reaction)
            }
        }

        result[entityId] = shouldSections
    }

    return result
}

func ymlParseEntityShoulds(
    _ chunks: [String: [String]],
    _ entities: [String]
) -> [Int: [String]] {
    var result = [Int: [String]]()
    var i = 0

    for entity in entities {
        var shoulds = [String]()

        guard let lines = chunks["\(entity):"] else {
            i += 1
            continue
        }

        var inShoulds = false

        for ln in lines {
            if ln.hasPrefix(YML_PREFIX_SHOULDS) {
                inShoulds = true
                continue
            }
            if 
                inShoulds &&
                otherLineIndent(ln) == YML_INDENT_SHOULD &&
                ln.hasSuffix(":")
            {
                let name = ln.dropFirst(YML_INDENT_SHOULD).dropLast()
                shoulds.append(String(name))
            }
        }

        result[i] = shoulds
        i += 1
    }

    return result
}

func ymlParseEntityTypes(
    _ chunks: [String: [String]],
    _ entities: [String]
) -> [Int: String] {
    var result = [Int: String]()
    var i = 0

    for entity in entities {
        var type = ""

        guard let lines = chunks["\(entity):"] else {
            i += 1
            continue
        }

        for ln in lines {
            if ln.hasPrefix(YML_PREFIX_TYPE) {
                type = String(ln.dropFirst(YML_PREFIX_TYPE.count))
                break
            }
        }

        result[i] = type
        i += 1
    }

    return result
}

func ymlParseOutputPaths(_ chunks: [String: [String]]) -> [OutputPath] {
    var paths = [OutputPath]()

    guard let lines = chunks[YML_PREFIX_OUTPUT] else {
        return paths
    }

    var currentPath = ""

    for ln in lines {
        // Type
        if ln.hasPrefix(YML_PREFIX_OUTPUT_TYPE) {
            var p = OutputPath()
            p.path = currentPath
            p.type = String(ln.dropFirst(YML_PREFIX_OUTPUT_TYPE.count))
            paths.append(p)
        }
        // Path
        else if ln.hasPrefix(YML_PREFIX_OUTPUT_PATH) {
            currentPath = String(ln.dropFirst(YML_PREFIX_OUTPUT_PATH.count).dropLast(1))
        }
    }

    return paths
}

func ymlParseVersion(_ chunks: [String: [String]]) -> Int {
    for key in chunks.keys {
        if key.hasPrefix(YML_PREFIX_VERSION) {
            let versionStr = key.dropFirst(YML_PREFIX_VERSION.count)
            if let version = Int(versionStr) {
                return version
            }
        }
    }

    return -1
}

